import React from 'react';

/** Voice session status. */
export type VoiceSessionStatus = 'idle' | 'listening' | 'transcribing' | 'speaking' | 'handoff';

/** A single transcript turn. */
export interface VoiceTranscriptTurn {
  /** Role of the speaker. */
  role: 'user' | 'assistant';
  /** Transcript text content. */
  text: string;
}

/** Props for the {@link VoiceSession} component. */
export interface VoiceSessionProps extends React.HTMLAttributes<HTMLDivElement> {
  /** Current session status. */
  status?: VoiceSessionStatus;
  /** Elapsed time string (e.g. "00:42"). */
  clock?: string;
  /** Array of waveform bar heights (0-1 normalized). */
  waveform?: number[];
  /** Transcript turns. */
  transcript?: VoiceTranscriptTurn[];
  /** Additional CSS class names. */
  className?: string;
  /** Control elements rendered at the bottom. */
  children?: React.ReactNode;
}

/**
 * Realtime voice session with waveform, transcript, and state indicators.
 * Renders a `<div>` with `sk-voice-session` and `data-status`.
 */
export const VoiceSession = React.forwardRef<HTMLDivElement, VoiceSessionProps>(
  ({ status = 'idle', clock, waveform, transcript, className, children, ...rest }, ref) => (
    <div
      ref={ref}
      className={`sk-voice-session${className ? ` ${className}` : ''}`}
      data-status={status}
      {...rest}
    >
      {clock && <div className="sk-voice-session__clock">{clock}</div>}
      {waveform && waveform.length > 0 && (
        <div className="sk-voice-session__waveform">
          {waveform.map((h, i) => (
            <div
              key={i}
              className="sk-voice-session__waveform-bar"
              style={{ height: `${Math.max(2, h * 32)}px` }}
            />
          ))}
        </div>
      )}
      {transcript && transcript.length > 0 && (
        <div className="sk-voice-session__transcript">
          {transcript.map((turn, i) => (
            <div key={i} className="sk-voice-session__turn" data-role={turn.role}>
              {turn.text}
            </div>
          ))}
        </div>
      )}
      {children && <div className="sk-voice-session__controls">{children}</div>}
    </div>
  ),
);

VoiceSession.displayName = 'VoiceSession';

/**
 * skeehn — VoiceSession Component
 *
 * @component sk-voice-session
 * @statuses  idle | listening | transcribing | speaking | handoff
 * @states    [data-loading] | [data-skeleton]
 * @slots     __clock | __waveform | __waveform-bar | __transcript | __turn | __controls
 * @features  Waveform visualization, live transcript, status border, role-based turn styling
 * @a11y      aria-live on transcript, status communicated via text + color
 * @print     Transcript visible, controls hidden
 */

.sk-voice-session {
  font-family: var(--sk-font-mono);
  font-size: var(--sk-font-size-sm);
  line-height: var(--sk-line-height);
  color: hsl(var(--sk-foreground));
  background: hsl(var(--sk-background));
  border: 1px solid hsl(var(--sk-border-color));
  padding: var(--sk-space-4);
  display: flex;
  flex-direction: column;
  gap: var(--sk-space-3);
}

/* Status indicator */
.sk-voice-session[data-status="idle"] { opacity: 0.7; }
.sk-voice-session[data-status="listening"] { border-color: hsl(var(--sk-primary)); }
.sk-voice-session[data-status="transcribing"] { border-color: hsl(var(--sk-accent, var(--sk-primary))); }
.sk-voice-session[data-status="speaking"] { border-color: hsl(var(--sk-success, var(--sk-primary))); }
.sk-voice-session[data-status="handoff"] { opacity: 0.5; }

/* Clock */
.sk-voice-session__clock {
  font-family: var(--sk-font-mono);
  font-size: var(--sk-font-size-xs, var(--sk-font-size-sm));
  color: hsl(var(--sk-muted, var(--sk-foreground)));
  letter-spacing: 0.1em;
}

/* Waveform */
.sk-voice-session__waveform {
  display: flex;
  align-items: center;
  gap: var(--sk-space-1);
  height: 2rem;
}

.sk-voice-session__waveform-bar {
  width: 3px;
  background: hsl(var(--sk-primary));
  border-radius: 1px;
  transition: height 0.1s ease;
}

/* Transcript */
.sk-voice-session__transcript {
  display: flex;
  flex-direction: column;
  gap: var(--sk-space-2);
  max-height: 12rem;
  overflow-y: auto;
}

.sk-voice-session__turn {
  font-family: var(--sk-font-mono);
  font-size: var(--sk-font-size-sm);
  color: hsl(var(--sk-foreground));
  padding: var(--sk-space-1) var(--sk-space-2);
  border-left: 2px solid hsl(var(--sk-border-color));
}

.sk-voice-session__turn[data-role="user"] {
  border-left-color: hsl(var(--sk-primary));
}

.sk-voice-session__turn[data-role="assistant"] {
  border-left-color: hsl(var(--sk-muted, var(--sk-border)));
}

/* Controls */
.sk-voice-session__controls {
  display: flex;
  gap: var(--sk-space-2);
  align-items: center;
}

/* Loading */
.sk-voice-session[data-loading] { pointer-events: none; opacity: 0.6; }
.sk-voice-session[data-loading] .sk-voice-session__waveform { opacity: 0.3; }

/* Skeleton */
.sk-voice-session[data-skeleton] .sk-voice-session__waveform,
.sk-voice-session[data-skeleton] .sk-voice-session__transcript,
.sk-voice-session[data-skeleton] .sk-voice-session__clock {
  background: linear-gradient(90deg, hsl(var(--sk-muted)) 25%, hsl(var(--sk-accent)) 50%, hsl(var(--sk-muted)) 75%);
  background-size: 200% 100%;
  animation: sk-card-shimmer 1.8s ease-in-out infinite;
  border-radius: var(--sk-radius);
  color: transparent;
}

.sk-voice-session[data-skeleton] .sk-voice-session__waveform-bar { display: none; }
.sk-voice-session[data-skeleton] .sk-voice-session__turn { visibility: hidden; }

@media print {
  .sk-voice-session { border: 1px solid hsl(var(--sk-foreground)); }
  .sk-voice-session__waveform { display: none; }
  .sk-voice-session__controls { display: none; }
  .sk-voice-session__clock { display: none; }
  .sk-voice-session[data-skeleton] { display: none; }
}

/* Reduced motion */
@media (prefers-reduced-motion: reduce) {
  .sk-voice-session__waveform-bar { transition: none; }
  .sk-voice-session[data-skeleton] .sk-voice-session__waveform,
  .sk-voice-session[data-skeleton] .sk-voice-session__transcript,
  .sk-voice-session[data-skeleton] .sk-voice-session__clock { animation: none; background: hsl(var(--sk-muted)); }
}
